<script setup lang="ts">
import {getRequestError} from '~/utils/errors'
definePageMeta({layout:false,middleware:'member'})
useSeoMeta({title:'Change password · BARNALI',robots:'noindex,nofollow'})
const api=useApi();const auth=useAuth();const current=ref('');const next=ref('');const confirm=ref('');const busy=ref(false);const error=ref('')
async function submit(){error.value='';if(next.value.length<12){error.value='Use at least 12 characters for your new password.';return}if(next.value!==confirm.value){error.value='The new passwords do not match.';return}busy.value=true;try{await api.request('/auth/password/change',{method:'POST',body:{currentPassword:current.value,newPassword:next.value}});auth.user.value=null;auth.checked.value=true;await navigateTo('/login?passwordChanged=1')}catch(e:unknown){error.value=getRequestError(e,'Password could not be changed. Please check your current password.')}finally{busy.value=false}}
</script>
<template><main class="auth-panel-wrap"><section class="auth-panel surface surface-pad"><BarnaliBrand compact/><span class="eyebrow">Account security</span><h1 class="serif-title">Change your password</h1><p class="muted">A new passphrase must contain at least 12 characters. Changing it signs out existing sessions.</p><p v-if="error" class="notice notice--error" role="alert">{{error}}</p><form class="auth-form" @submit.prevent="submit"><div class="form-field"><label for="current-password">Current password</label><input id="current-password" v-model="current" class="input" type="password" autocomplete="current-password" required maxlength="72"></div><div class="form-field"><label for="new-password">New password</label><input id="new-password" v-model="next" class="input" type="password" autocomplete="new-password" minlength="12" maxlength="72" required></div><div class="form-field"><label for="confirm-password">Confirm new password</label><input id="confirm-password" v-model="confirm" class="input" type="password" autocomplete="new-password" minlength="12" maxlength="72" required></div><button class="btn" :disabled="busy">{{busy?'Updating…':'Update password'}}</button></form></section></main></template>
